import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv1d_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv1d_forward_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels, int kernel_size,
    int input_length, int stride, int padding, int dilation, int groups,
    int output_length)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * output_length) return;

    int b = idx / (out_channels * output_length);
    int oc = (idx / output_length) % out_channels;
    int l_out = idx % output_length;

    int group = oc / (out_channels / groups);
    int in_channels_per_group = in_channels / groups;

    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int l_in = l_out * stride - padding + k * dilation;
        if (l_in < 0 || l_in >= input_length) continue;

        for (int ic = 0; ic < in_channels_per_group; ++ic) {
            int input_idx = b * in_channels * input_length + (group * in_channels_per_group + ic) * input_length + l_in;
            int weight_idx = oc * (in_channels_per_group * kernel_size) + ic * kernel_size + k;

            sum += input[input_idx] * weight[weight_idx];
        }
    }

    if (bias != nullptr) {
        sum += bias[oc];
    }

    output[idx] = sum;
}

torch::Tensor conv1d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups) {

    input = input.contiguous();
    weight = weight.contiguous();
    if (bias.defined()) bias = bias.contiguous();

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int output_length = ((input_length + 2*padding - dilation*(kernel_size-1) -1)/stride) + 1;
    auto output = torch::zeros({batch_size, out_channels, output_length}, input.options());

    int num_elements = batch_size * out_channels * output_length;
    int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;

    conv1d_forward_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        kernel_size,
        input_length,
        stride,
        padding,
        dilation,
        groups,
        output_length);

    return output;
}
"""

conv1d_cpp_source = """
torch::Tensor conv1d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv1d_ext = load_inline(
    name='conv1d_ext',
    cpp_sources=conv1d_cpp_source,
    cuda_sources=conv1d_cuda_source,
    functions=['conv1d_cuda_forward'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(out_channels, in_channels//groups, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv1d_ext.conv1d_cuda_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.Tensor().to(x.device),
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )
